LoadPermissionData.syntax_text:
private DataTable LoadPermissionData(string formName)
        {
            DataTable dataTable = new DataTable();

            using SqlConnection connection = MainClass.ConnObj();
            using SqlDataAdapter adapter = new SqlDataAdapter(
                "select IS_New, IS_Save, IS_Delete, IS_Search, IS_Print, Forms.id " +
                "from User_Permissions, Forms " +
                "where User_Permissions.Form_id = Forms.id " +
                "and Forms.FormName = @FormName " +
                "and user_id = @UserId",
                connection);

            adapter.SelectCommand.Parameters.AddWithValue("@FormName", formName);
            adapter.SelectCommand.Parameters.AddWithValue("@UserId", MainClass.UserID);

            adapter.Fill(dataTable);
            return dataTable;
        }

GetBool.syntax_text:
private bool GetBool(DataRow row, string columnName)
        {
            try
            {
                if (row == null || !row.Table.Columns.Contains(columnName))
                    return false;

                return row[columnName] != DBNull.Value
                    && Convert.ToBoolean(row[columnName]);
            }
            catch
            {
                return false;
            }
        }

GetTargetButtons.syntax_text:
private IEnumerable<ButtonBase> GetTargetButtons(FrameworkElement rootElement)
        {
            // نحاول أولاً إيجاد pnlOperBtns إن وجد
            FrameworkElement operationPanel = FindElementByName(rootElement, "pnlOperBtns");

            if (operationPanel != null)
            {
                List<ButtonBase> panelButtons = FindVisualChildren<ButtonBase>(operationPanel).ToList();
                if (panelButtons.Count > 0)
                    return panelButtons;
            }

            // fallback: البحث في كامل النافذة
            return FindVisualChildren<ButtonBase>(rootElement).ToList();
        }

ResolveFormName.syntax_text:
private string ResolveFormName(FrameworkElement rootElement)
        {
            if (rootElement == null)
                return string.Empty;

            // الأولوية للاسم المصرح به
            if (!string.IsNullOrWhiteSpace(rootElement.Name))
                return rootElement.Name.Trim();

            // fallback: اسم الكلاس
            return rootElement.GetType().Name.Trim();
        }

ApplyEditAddPermission.syntax_text:
public static void ApplyEditAddPermission(
            object frm,
            bool IsNew,
            FormPermission frmPer)
        {
            if (frm == null || frmPer == null) return;

            if (frm is System.Windows.Window window)
                ApplyEditAddPermissionInternal(window, IsNew, frmPer);
            else if (frm is System.Windows.FrameworkElement fe)
                ApplyEditAddPermissionInternal(fe, IsNew, frmPer);
        }

ApplyEditAddPermissionInternal.syntax_text:
private static void ApplyEditAddPermissionInternal(
            System.Windows.FrameworkElement root,
            bool IsNew,
            FormPermission frmPer)
        {
            var buttons = FindVisualChildren<System.Windows.Controls.Button>(root);

            foreach (var button in buttons)
            {
                if (string.IsNullOrWhiteSpace(button.Name)) continue;

                string name = button.Name.Trim();

                bool isSaveBtn =
                    string.Equals(name, "btnSave", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(name, "btnSavePrint",
                        StringComparison.OrdinalIgnoreCase);

                if (!isSaveBtn) continue;

                if (!frmPer.Addable && IsNew)
                {
                    button.IsEnabled = false;
                    button.Background = System.Windows.Media.Brushes.Gray;
                }
                else if (frmPer.Addable && IsNew)
                {
                    button.IsEnabled = true;
                }
                else if (!frmPer.Editable && !IsNew)
                {
                    button.IsEnabled = false;
                    button.Background = System.Windows.Media.Brushes.Gray;
                }
                else if (frmPer.Editable && !IsNew)
                {
                    button.IsEnabled = true;
                }
            }
        }

