EnsureOpen.syntax_text:
private void EnsureOpen(SqlConnection connection)
        {
            if (!IsLoaded) return;
            if (connection.State != ConnectionState.Open)
                connection.Open();
        }

EnsureClose.syntax_text:
private void EnsureClose(SqlConnection connection)
        {
