                Panel1.Visibility = Visibility.Visible;
                txtCheckNo.Text = checkNo;
                txtBankCheck.Text = checkbank;
                txtCheckDate.DateTime = checkDate;
                cmbCheckType.SelectedIndex = checkState - 1;
            }

